mapper.select:
select s.* from student s left join clazz c on s.clazz_id=c.id
and s.name like concat('%', #{param.name}, '%')
and s.degree in (#{param.degree})
and s.clazz_id = #{param.clazzId}
order by s.update_time desc limit #{start},#{pageSize}

mapper.update:
update student
name=#{name}, no=#{no}, gender=#{gender}, phone=#{phone}, id_card=#{idCard}, is_college=#{isCollege}, address=#{address}, degree=#{degree}, graduation_date=#{graduationDate}, clazz_id=#{clazzId}, violation_count=#{violationCount}, violation_score=#{violationScore}, create_time=#{createTime}, update_time=#{updateTime},
where id=#{id}
